/*
  AmeVarName was `AmeTokenName | AmeAliasName` while the legacy --port-*
  aliases existed. They were deleted; this reference was not, so the published
  tokens.d.ts named a type it never declared and did not compile.

  Nothing here caught it because tsconfig sets skipLibCheck, which suppresses
  errors in .d.ts files by design. The repo's own typecheck is therefore blind
  to the one file it publishes for other people to typecheck against, and a
  consumer without that flag inherits the error we cannot see.
*/
/** Anything `token()` will accept. */
export type AmeVarName = AmeTokenName

/** The recipes this system compiles. */
export type AmeRecipeName =
  | 'expertise-card'

/** Each recipe's settable axes. A media axis is selected by the viewport, so it is not here. */
export interface AmeRecipeVariants {
  'expertise-card': {
    layout?: 'expertise' | 'term-sheet'
  }
}

/** Each recipe's slots. */
export interface AmeRecipeSlots {
  'expertise-card': 'root' | 'list' | 'cell' | 'block' | 'label' | 'value'
}

export interface AmeRecipeSpec {
  readonly class: string
  readonly element: string
  readonly slots: readonly string[]
  readonly axes: Readonly<
    Record<string, { readonly attribute?: string; readonly default: string; readonly contexts: readonly string[] }>
  >
}

export declare const RECIPES: Readonly<Record<AmeRecipeName, AmeRecipeSpec>>
export declare function token(name: AmeVarName): string
export declare function slot<K extends AmeRecipeName>(name: K, part: AmeRecipeSlots[K]): string
export declare function recipe<K extends AmeRecipeName>(
  name: K,
  variants?: AmeRecipeVariants[K],
): { className: string } & Record<string, string>

